package com.metaplatform.agent.evidence;
import jakarta.persistence.*; import lombok.*; import java.time.Instant;
@Entity @Table(name="evidence") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class EvidenceEntity { @Id @Column(name="evidence_id",length=64) private String evidenceId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32) private EvidenceType type; @Column(nullable=false,columnDefinition="TEXT") private String ref; @Column(columnDefinition="TEXT") private String fragment; @Column(name="source_uri",columnDefinition="TEXT") private String sourceUri; @Column(name="captured_at",nullable=false) private Instant capturedAt; @Column(name="captured_by",nullable=false,length=128) private String capturedBy; @Column(length=128) private String concept; @Column(name="object_id",length=128) private String objectId; @Column(name="tool_call_id",length=128) private String toolCallId; @Column(name="envelope_id",nullable=false,length=64) private String envelopeId; }
